function makeDashboardInsights(key){const cats=dashboardCategorySpending(key).filter(c=>c.total>0),prevKey=(()=>{const [y,m]=key.split('-').map(Number);return monthKey(new Date(y,m-2,1))})(),prev=dashboardCategorySpending(prevKey),txs=dashboardMonthTx(key),tiny=txs.filter(t=>t.type==='expense'&&Math.abs(+t.amount)<=15),m=dashboardMonthSums(key);const result=[];if(cats[0])result.push({icon:category(cats[0].name).icon,title:`${cats[0].name} is je grootste categorie`,text:`Je hebt ${money(cats[0].total)} uitgegeven in deze categorie${m.expense>0?` (${(cats[0].total/m.expense*100).toFixed(0)}% van je uitgaven)`:''}.`});const rise=cats.map(c=>({name:c.name,value:c.total-(prev.find(p=>p.name===c.name)?.total||0)})).sort((a,b)=>b.value-a.value)[0];if(rise&&rise.value>0&&prev.length)result.push({icon:'↗',title:`Stijging bij ${rise.name}`,text:`Je uitgaven liggen ${money(rise.value)} hoger dan vorige maand.`});if(tiny.length)result.push({icon:'∑',title:'Kleine uitgaven tellen op',text:`${tiny.length} uitgaven van € 15 of minder komen samen uit op ${money(sum(tiny,t=>t.amount))}.`});if(m.net<0)result.push({icon:'!',title:'Negatieve cashflow binnen dit overzicht',text:`De uitgaven liggen ${money(Math.abs(m.net))} boven de inkomsten voor ${monthName(key)}.`});if(!result.length)result.push({icon:'✦',title:'Je overzicht wordt opgebouwd',text:'Meer transacties geven een beter beeld van je inkomsten, uitgaven en categorieën binnen deze rekening.'});return result.slice(0,3)}
