function isoDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function dateInMonth(year,monthIndex,day){return new Date(year,monthIndex,Math.min(day,new Date(year,monthIndex+1,0).getDate()))}
function billDateForMonth(b,key){return billDatesForMonth(b,key)[0]||null}
function nextBillDate(b){const todayMonth=monthKey(new Date());return billDateForMonth(b,todayMonth)||isoDate(parseDate(b.nextDate||dateNow()))}
function addFrequency(d,f){const x=new Date(d);if(f==='weekly')x.setDate(x.getDate()+7);else if(f==='yearly')x.setFullYear(x.getFullYear()+1);else if(f==='quarterly')x.setMonth(x.getMonth()+3);else x.setMonth(x.getMonth()+1);return x}
