function goalModal(id=null){const old=id?state.goals.find(g=>g.id===id):null;const g=old||{name:'',target:'',saved:0,deadline:'',icon:'◎'};const body=`<form id="goalForm"><div class="form-grid"><div class="form-field wide"><label for="goalName">Naam spaardoel *</label><input id="goalName" maxlength="80" required value="${esc(g.name)}" placeholder="Bijv. Noodbuffer"></div><div class="form-field"><label for="goalTarget">Doelbedrag (€) *</label><input id="goalTarget" type="number" min="0.01" step="0.01" required value="${esc(g.target)}"></div><div class="form-field"><label for="goalSaved">Al gespaard (€)</label><input id="goalSaved" type="number" min="0" step="0.01" value="${esc(g.saved||0)}"></div><div class="form-field"><label for="goalDeadline">Streefdatum (optioneel)</label><input id="goalDeadline" type="date" value="${esc(g.deadline||'')}"></div><div class="form-field"><label for="goalIcon">Symbool</label><select id="goalIcon">${[['◎','Doel'],['✈','Vakantie'],['⌂','Woning'],['◈','Aankoop'],['✚','Buffer'],['🚗','Auto'],['✦','Vrij']].map(([v,l])=>`<option value="${v}" ${v===g.icon?'selected':''}>${v} ${l}</option>`).join('')}</select></div></div></form>`;showModal(old?'Spaardoel bewerken':'Spaardoel aanmaken','Stel een doelbedrag in en volg je voortgang.',body,`<button class="btn" id="cancelGoal" type="button">Annuleren</button><div class="modal-footer-right">${old?'<button class="btn danger" id="deleteGoalInModal" type="button">Verwijderen</button>':''}<button class="btn primary" form="goalForm">Doel opslaan</button></div>`);document.getElementById('cancelGoal').onclick=closeModal;document.getElementById('deleteGoalInModal')?.addEventListener('click',()=>deleteGoal(id));document.getElementById('goalForm').onsubmit=e=>{e.preventDefault();const obj={...(old||{}),id:old?.id||uid(),name:document.getElementById('goalName').value.trim(),target:+document.getElementById('goalTarget').value,saved:+document.getElementById('goalSaved').value||0,deadline:document.getElementById('goalDeadline').value,icon:document.getElementById('goalIcon').value};if(!obj.name||!(obj.target>0)||obj.saved<0){toast('Controleer de ingevulde bedragen.','error');return}if(old&&Number(old.saved)!==obj.saved){obj.contributions=[...(old.contributions||[]),{id:uid(),date:dateNow(),amount:obj.saved-Number(old.saved||0),correction:true}]}if(old)state.goals=state.goals.map(x=>x.id===id?obj:x);else state.goals.push(obj);if(!save())return;closeModal();renderPlanning();toast('Spaardoel opgeslagen.')}}
function deleteGoal(id){const g=state.goals.find(x=>x.id===id);if(g&&confirm('Spaardoel “'+g.name+'” naar de prullenbak?')){if(!softDeleteFinance('goals',id))return;closeModal();renderPlanning();toast('Spaardoel naar prullenbak.')}}
function contributeGoal(id){const g=state.goals.find(x=>x.id===id);if(!g)return;const body=`<form id="contributeForm"><div class="muted-box">${esc(g.name)} · huidig bedrag ${money(g.saved)} van ${money(g.target)}</div><div class="form-field" style="margin-top:15px"><label for="contributeAmount">Bedrag om toe te voegen (€)</label><input id="contributeAmount" type="number" min="0.01" step="0.01" required placeholder="Bijv. 50"></div><div class="form-field" style="margin-top:12px"><label for="contributeType">Boek als</label><select id="contributeType"><option value="save">Alleen voortgang spaardoel</option><option value="tx">Spaardoel én uitgavetransactie (niet aanbevolen voor gewone inleg)</option></select><small>Een inleg van je betaalrekening naar spaargeld is meestal een verplaatsing, geen consumptieve uitgave.</small></div></form>`;showModal('Bedrag toevoegen',`Je spaardoel bijwerken: ${g.name}`,body,`<button class="btn" id="cancelContrib">Annuleren</button><button class="btn primary" form="contributeForm">Bedrag toevoegen</button>`);document.getElementById('cancelContrib').onclick=closeModal;document.getElementById('contributeForm').onsubmit=e=>{e.preventDefault();const v=+document.getElementById('contributeAmount').value;if(!(v>0)){toast('Vul een bedrag groter dan nul in.','error');return}g.contributions=Array.isArray(g.contributions)?g.contributions:[];g.contributions.push({id:uid(),date:dateNow(),amount:v});g.saved=Math.round(((+g.saved||0)+v)*100)/100;if(document.getElementById('contributeType').value==='tx'){state.transactions.push({id:uid(),type:'expense',date:dateNow(),description:`Inleg spaardoel: ${g.name}`,amount:v,category:'Overig',note:'Automatisch toegevoegd via spaardoel',createdAt:new Date().toISOString()})}if(!save())return;closeModal();renderPlanning();renderDashboard();toast('Voortgang bijgewerkt.')}}
function downloadBlob(filename,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function transactionReceipts(transactionId){return (state.receipts||[]).filter(r=>r.transactionId===transactionId)}
function openReceiptFromTransaction(receiptId){const r=(state.receipts||[]).find(x=>x.id===receiptId);if(!r)return;closeModal();selectedMonth=String(r.date||dateNow()).slice(0,7)||selectedMonth;changeView('receipts');const monthInput=document.getElementById('receiptMonth');if(monthInput)monthInput.value=selectedMonth;renderReceipts();setTimeout(()=>{const card=document.querySelector(`[data-receipt-card="${CSS.escape(receiptId)}"]`);card?.scrollIntoView({behavior:'smooth',block:'start'});},50)}
function receiptMonthValue(){return document.getElementById('receiptMonth')?.value||selectedMonth}
function receiptTransactions(month=receiptMonthValue()){return state.transactions.filter(t=>String(t.date||'').startsWith(month)&&['expense','refund'].includes(t.type)).sort((a,b)=>b.date.localeCompare(a.date))}
function receiptLinkedTx(receipt){return state.transactions.find(t=>t.id===receipt.transactionId)||null}
function receiptLinkOptions(selected='',month=receiptMonthValue()){const txs=state.transactions.filter(t=>String(t.date||'').startsWith(month)&&['expense','refund'].includes(t.type)).sort((a,b)=>b.date.localeCompare(a.date));return '<option value="">Niet gekoppeld</option>'+txs.map(t=>`<option value="${esc(t.id)}" ${t.id===selected?'selected':''}>${esc(t.date)} · ${esc(t.description)} · ${money(t.amount)}${t.merchant?' · '+esc(t.merchant):''}</option>`).join('')}
function receiptMatchesTransaction(r,t){if(r.total==null||Math.abs(Number(r.total)-Math.abs(Number(t.amount)))>=0.011)return false;const days=Math.abs((parseDate(r.date)-parseDate(t.date))/86400000);if(!Number.isFinite(days)||days>3)return false;const clean=x=>String(x||'').toLowerCase().replace(/[^a-z0-9]/g,'');const store=clean(r.store),merchant=clean(t.merchant||t.description);return !store||!merchant||store.includes(merchant)||merchant.includes(store)}
function renderReceipts(){const month=receiptMonthValue();const receipts=state.receipts.filter(r=>String(r.date||'').startsWith(month)).sort((a,b)=>String(b.date).localeCompare(String(a.date)));const txs=receiptTransactions(month);const linkedReceipts=receipts.filter(r=>r.transactionId&&state.transactions.some(t=>t.id===r.transactionId));const linkedTxIds=new Set(linkedReceipts.map(r=>r.transactionId));const unlinkedTx=txs.filter(t=>!linkedTxIds.has(t.id));const unlinkedReceipts=receipts.filter(r=>!r.transactionId||!state.transactions.some(t=>t.id===r.transactionId));document.getElementById('receiptCount').textContent=`${receipts.length} ${receipts.length===1?'bon':'bonnen'}`;document.getElementById('receiptMonthStats').innerHTML=[['Bonnen',String(receipts.length)],['Gekoppeld',String(linkedReceipts.length)],['Transacties zonder bon',String(unlinkedTx.length)]].map(([l,v])=>`<div class="moneycoach-stat"><span>${l}</span><strong>${v}</strong></div>`).join('');const matches=[];unlinkedTx.forEach(t=>{const cand=receipts.filter(r=>!r.transactionId&&receiptMatchesTransaction(r,t));matches.push({type:cand.length?'check':'tx',tx:t,candidates:cand})});unlinkedReceipts.forEach(r=>{const cand=txs.filter(t=>!t.id||!linkedTxIds.has(t.id)).filter(t=>receiptMatchesTransaction(r,t));if(!cand.length)matches.push({type:'receipt',receipt:r,candidates:cand})});document.getElementById('receiptReconciliation').innerHTML=`<div class="setting-row"><div><b>${unlinkedTx.length} transactie(s) zonder gekoppelde bon</b><span>Niet elke transactie heeft een kassabon.</span></div></div><div class="setting-row"><div><b>${unlinkedReceipts.length} bon(nen) zonder gekoppelde transactie</b><span>Kan contant betaald zijn of nog gekoppeld moeten worden.</span></div></div>`+(matches.length?'<div class="receipt-audit-list">'+matches.map(m=>m.type==='check'?`<div class="muted-box">Mogelijke match voor <b>${esc(m.tx.description)}</b> (${money(m.tx.amount)}): er is een niet-gekoppelde bon met passend bedrag, datum en winkel. Controleer de koppeling.</div>`:m.type==='tx'?`<div class="muted-box"><b>Transactie zonder bon</b><br>${esc(m.tx.date)} · ${esc(m.tx.description)} · ${money(m.tx.amount)}</div>`:`<div class="muted-box"><b>Bon zonder transactie</b><br>${esc(m.receipt.date)} · ${esc(m.receipt.store||'Winkel onbekend')} · ${m.receipt.total==null?'bedrag onbekend':money(m.receipt.total)}</div>`).join('')+'</div>':'<div class="empty">Geen openstaande signalen op basis van deze eenvoudige controle.</div>');document.getElementById('receiptList').innerHTML=receipts.length?receipts.map(r=>{const linked=receiptLinkedTx(r);return `<div class="card receipt-card" data-receipt-card="${esc(r.id)}"><div class="card-head"><div><div class="card-title">${esc(r.store||'Winkel onbekend')}</div><div class="card-subtitle">${esc(r.date)} · ${r.total==null?'Totaal onbekend':money(r.total)}</div></div><span class="pill ${linked?'green':''}">${linked?'Gekoppeld':'Niet gekoppeld'}</span></div><div class="form-field"><label for="receiptLink-${esc(r.id)}">Koppeling aan transactie</label><select id="receiptLink-${esc(r.id)}" data-receipt-link="${esc(r.id)}">${receiptLinkOptions(r.transactionId||'')}</select>${linked?`<small>Transactie: ${esc(linked.description)} · ${money(linked.amount)} · ${esc(linked.date)}</small>`:''}</div>${r.structured?`<details style="margin-top:10px"><summary>Productgegevens en controles (${(r.structured.producten||[]).length} regels)</summary>${receiptValidationHtml(r.structured)}<pre class="receipt-raw-text">${esc(JSON.stringify(r.structured,null,2))}</pre></details>`:''}<details style="margin-top:10px"><summary>Bontekst bekijken</summary><pre class="receipt-raw-text">${esc(r.text||'')}</pre></details><div class="smartbuy-actions" style="margin-top:12px"><button class="btn sm" type="button" data-receipt-edit="${esc(r.id)}">Bewerken</button><button class="btn sm danger" type="button" data-receipt-delete="${esc(r.id)}">Verwijderen</button></div></div>`}).join(''):'<div class="card empty">Nog geen bonnen opgeslagen voor deze maand. Voeg hierboven een bon toe.</div>';document.querySelectorAll('[data-receipt-link]').forEach(sel=>sel.onchange=()=>{const r=state.receipts.find(x=>x.id===sel.dataset.receiptLink);if(!r)return;r.transactionId=sel.value||null;if(!save())return;renderReceipts();toast(r.transactionId?'Bon aan transactie gekoppeld.':'Bonkoppeling verwijderd.')});document.querySelectorAll('[data-receipt-delete]').forEach(b=>b.onclick=()=>{const r=state.receipts.find(x=>x.id===b.dataset.receiptDelete);if(r&&confirm(`Bon van ${r.store||r.date} verwijderen?`)){if(!softDeleteFinance('receipts',r.id))return;renderReceipts();toast('Bon verwijderd.')}});document.querySelectorAll('[data-receipt-edit]').forEach(b=>b.onclick=()=>editReceipt(b.dataset.receiptEdit));document.getElementById('receiptLinkTx').innerHTML=receiptLinkOptions(document.getElementById('receiptLinkTx').value||'');}
function editReceipt(id){const r=state.receipts.find(x=>x.id===id);if(!r)return;document.getElementById('receiptStore').value=r.store||'';document.getElementById('receiptDate').value=r.date||dateNow();document.getElementById('receiptTotal').value=r.total??'';document.getElementById('receiptNumber').value=r.number||'';document.getElementById('receiptText').value=r.text||'';document.getElementById('receiptImportJson').value=r.structured?JSON.stringify(r.structured,null,2):'';document.getElementById('receiptForm').dataset.receiptJson=r.structured?JSON.stringify(r.structured):'';document.getElementById('receiptLinkTx').innerHTML=receiptLinkOptions(r.transactionId||'',String(r.date||'').slice(0,7));document.getElementById('receiptLinkTx').value=r.transactionId||'';document.getElementById('receiptForm').dataset.editId=id;document.getElementById('receiptForm').scrollIntoView({behavior:'smooth',block:'start'})}
function receiptParseText(text){const lines=String(text||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);const store=lines.slice(0,4).sort((a,b)=>b.length-a.length)[0]||'';const dateMatch=String(text).match(/\b(\d{1,2})[./-](\d{1,2})[./-](\d{2,4})\b/);let date=dateNow();if(dateMatch){let y=+dateMatch[3];if(y<100)y+=2000;date=`${y}-${String(+dateMatch[2]).padStart(2,'0')}-${String(+dateMatch[1]).padStart(2,'0')}`}const values=[...String(text).matchAll(/(?:totaal\s*(?:te betalen)?|te betalen|totaalbedrag)[^\d\n]{0,18}(\d{1,4}[,.]\d{2})/ig)].map(m=>m[1]);let total=null;if(values.length){const v=values[values.length-1].replace(',','.');if(Number.isFinite(+v))total=+v}return {store,date,total}}
async function runReceiptOcr(){const file=document.getElementById('receiptImage').files?.[0];if(!file){toast('Kies eerst een bonfoto.','error');return}const status=document.getElementById('receiptOcrStatus'),btn=document.getElementById('receiptRunOcr');btn.disabled=true;status.textContent='OCR laden…';try{if(!window.Tesseract){await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js';script.onload=resolve;script.onerror=()=>reject(new Error('OCR-software kon niet worden geladen. Controleer je internetverbinding.'));document.head.appendChild(script)})}status.textContent='Bon wordt lokaal herkend…';const result=await Tesseract.recognize(file,'nld+eng',{logger:m=>{if(m.status==='recognizing text')status.textContent=`Tekst herkennen: ${Math.round((m.progress||0)*100)}%`}});const text=result.data.text||'';document.getElementById('receiptText').value=text;const parsed=receiptParseText(text);if(!document.getElementById('receiptStore').value)document.getElementById('receiptStore').value=parsed.store;if(!document.getElementById('receiptDate').value||document.getElementById('receiptDate').value===dateNow())document.getElementById('receiptDate').value=parsed.date;if(!document.getElementById('receiptTotal').value&&parsed.total!=null)document.getElementById('receiptTotal').value=parsed.total.toFixed(2);status.textContent=`Klaar: ${text.length} tekens herkend. Controleer de tekst en bedragen.`;toast('Bon herkend. Controleer alle gegevens voordat je opslaat.')}catch(e){status.textContent=e.message||'Tekstherkenning mislukt.';toast(status.textContent,'error')}finally{btn.disabled=false}}
function receiptChatGPTPrompt(){return `Analyseer de bijgevoegde kassabonfoto nauwkeurig. Geef uitsluitend één geldig JSON-object terug, zonder markdown-codeblokken of extra uitleg. Lees alle productregels, aantallen, eenheidsprijzen, regelbedragen, statiegeld, kortingen, subtotaal, totaal, betaalwijzen en btw voor zover zichtbaar. Raad niets: gebruik null voor onbekende waarden en zet twijfelgevallen in onzekerheden. Controleer of subtotaal minus kortingen gelijk is aan totaal en of betaalbedragen optellen tot het totaal. Bedragen zijn numeriek in euro's, decimalen met een punt. Gebruik exact deze structuur: {"winkel":"","datum":"YYYY-MM-DD","tijd":null,"bonnummer":null,"valuta":"EUR","subtotaal":null,"korting_totaal":null,"totaal":null,"betaalwijzen":[{"methode":"","bedrag":null}],"btw":[{"tarief":null,"grondslag":null,"bedrag":null}],"producten":[{"naam":"","aantal":1,"eenheid":null,"prijs_per_eenheid":null,"bedrag":null,"statiegeld":false,"korting":null,"onzeker":false}],"onzekerheden":[],"controles":{"subtotaal_min_kortingen":null,"betaalbedragen_som":null,"totaal_klopt":null}}. Neem ook producten met korting als productregels op en verwerk korting niet dubbel in het totaal. Markeer productregels waarvan naam, aantal of prijs niet duidelijk is met onzeker:true. Gebruik alleen informatie die daadwerkelijk op de bon staat.`}
function copyTextFallback(text){const ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.select();let ok=false;try{ok=document.execCommand('copy')}catch(e){}ta.remove();return ok}
async function copyReceiptPrompt(){const prompt=receiptChatGPTPrompt();try{await navigator.clipboard.writeText(prompt);toast('Bon-opdracht gekopieerd. Upload de bonfoto in ChatGPT en plak de opdracht.')}catch(e){if(copyTextFallback(prompt))toast('Bon-opdracht gekopieerd. Upload de bonfoto in ChatGPT en plak de opdracht.');else{document.getElementById('receiptImportJson').value=prompt;toast('Kopiëren lukte niet; de opdracht staat tijdelijk in het tekstveld.','error')}}}
function openReceiptChatGPT(){const prompt=receiptChatGPTPrompt();copyReceiptPrompt().finally(()=>window.open('https://chatgpt.com/?q='+encodeURIComponent(prompt),'_blank','noopener,noreferrer'))}
function receiptParseJsonInput(raw){let text=String(raw||'').trim();text=text.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');const first=text.indexOf('{'),last=text.lastIndexOf('}');if(first<0||last<first)throw new Error('Geen JSON-object gevonden. Kopieer het volledige JSON-resultaat van ChatGPT.');text=text.slice(first,last+1);let d,firstError;try{d=JSON.parse(text)}catch(e){firstError=e;/* ChatGPT sometimes escapes JSON array brackets as \[ and \]. These are not valid JSON outside a string; normalize only those bracket escapes and retry. */const normalized=text.replace(/\\([\[\]])/g,'$1');try{d=JSON.parse(normalized)}catch(second){throw new Error('JSON is ongeldig. De app heeft ook geprobeerd onnodige backslashes vóór [ en ] te herstellen. Kopieer het volledige JSON-object opnieuw. Details: '+(second.message||firstError.message))}}if(!d||typeof d!=='object'||Array.isArray(d))throw new Error('Het resultaat is geen JSON-object.');if(!Array.isArray(d.producten))throw new Error('Het JSON-resultaat bevat geen lijst "producten". Gebruik de bon-opdracht uit Memento.');return d}
function receiptJsonToReadable(d){const out=[];out.push(`WINKEL: ${d.winkel||'Onbekend'}`,`DATUM: ${d.datum||'Onbekend'}`);if(d.tijd)out.push(`TIJD: ${d.tijd}`);if(d.bonnummer)out.push(`BONNUMMER: ${d.bonnummer}`);out.push('', 'PRODUCTREGELS:');(d.producten||[]).forEach((p,i)=>{const bits=[`${i+1}. ${p.naam||'Onbekend product'}`,`aantal: ${p.aantal??'?'}`];if(p.eenheid)bits.push(`eenheid: ${p.eenheid}`);if(p.prijs_per_eenheid!=null)bits.push(`prijs/stuk: € ${Number(p.prijs_per_eenheid).toFixed(2)}`);if(p.bedrag!=null)bits.push(`bedrag: € ${Number(p.bedrag).toFixed(2)}`);if(p.statiegeld)bits.push('statiegeld');if(p.korting!=null)bits.push(`korting: € ${Number(p.korting).toFixed(2)}`);if(p.onzeker)bits.push('CONTROLE NODIG');out.push(bits.join(' | '))});out.push('',`Subtotaal: ${d.subtotaal==null?'onbekend':'€ '+Number(d.subtotaal).toFixed(2)}`,`Totale korting: ${d.korting_totaal==null?'onbekend':'€ '+Number(d.korting_totaal).toFixed(2)}`,`TOTAAL: ${d.totaal==null?'onbekend':'€ '+Number(d.totaal).toFixed(2)}`);if(d.betaalwijzen?.length){out.push('','BETALINGEN:');d.betaalwijzen.forEach(x=>out.push(`${x.methode||'Methode onbekend'}: ${x.bedrag==null?'onbekend':'€ '+Number(x.bedrag).toFixed(2)}`))}if(d.btw?.length){out.push('','BTW:');d.btw.forEach(x=>out.push(`${x.tarief??'?'}% | grondslag ${x.grondslag??'?'} | btw ${x.bedrag??'?'}`))}if(d.onzekerheden?.length){out.push('','ONZEKERHEDEN:');d.onzekerheden.forEach(x=>out.push(`- ${typeof x==='string'?x:JSON.stringify(x)}`))}if(d.controles)out.push('',`CONTROLE SUBTOTAAL - KORTINGEN: ${d.controles.subtotaal_min_kortingen??'onbekend'}`,`SOM BETALINGEN: ${d.controles.betaalbedragen_som??'onbekend'}`,`TOTAALCONTROLE: ${d.controles.totaal_klopt??'onbekend'}`);return out.join('\n')}
function receiptValidateStructured(d){const checks=[];const num=v=>v==null||v===''?null:Number(v);const sub=num(d.subtotaal),disc=num(d.korting_totaal),tot=num(d.totaal);if(sub!=null&&disc!=null&&tot!=null){const calc=Math.round((sub-disc)*100)/100;checks.push({label:'Subtotaal min korting',ok:Math.abs(calc-tot)<0.011,detail:`${calc.toFixed(2)} versus ${tot.toFixed(2)}`})}else checks.push({label:'Subtotaal min korting',ok:null,detail:'Onvoldoende bedragen'});if(Array.isArray(d.betaalwijzen)&&d.betaalwijzen.length&&tot!=null){const paid=Math.round(d.betaalwijzen.reduce((a,x)=>a+(Number(x.bedrag)||0),0)*100)/100;checks.push({label:'Betalingen optellen',ok:Math.abs(paid-tot)<0.011,detail:`${paid.toFixed(2)} versus ${tot.toFixed(2)}`})}else checks.push({label:'Betalingen optellen',ok:null,detail:'Geen volledige betaalgegevens'});const lines=Array.isArray(d.producten)?d.producten:[];const discountLines=lines.filter(x=>Number(x.bedrag)<0);const discountsOnProducts=lines.filter(x=>Number(x.bedrag)>=0&&Number(x.korting)>0);if(discountLines.length&&discountsOnProducts.length){checks.push({label:'Kortingen niet dubbel tellen',ok:null,detail:`${discountsOnProducts.length} productregel(s) hebben een korting en ${discountLines.length} aparte negatieve bonusregel(s). De korting moet alleen eenmaal in de totaalberekening meetellen.`})}const uncertain=lines.filter(x=>x.onzeker).length;checks.push({label:'Productregels controleren',ok:uncertain===0,detail:uncertain?`${uncertain} regel(s) gemarkeerd als onzeker`:'Geen productregels expliciet gemarkeerd als onzeker'});return checks}
function receiptValidationHtml(d){const checks=receiptValidateStructured(d);return '<div class="muted-box" style="margin-top:10px"><b>Importcontrole</b>'+checks.map(c=>`<div style="margin-top:5px">${c.ok===true?'✓':c.ok===false?'!':'•'} ${esc(c.label)}: ${esc(c.detail)}</div>`).join('')+'</div>'}
function applyReceiptJson(){const status=document.getElementById('receiptImportStatus');try{const d=receiptParseJsonInput(document.getElementById('receiptImportJson').value);if(d.winkel)document.getElementById('receiptStore').value=String(d.winkel);if(/^\d{4}-\d{2}-\d{2}$/.test(String(d.datum||'')))document.getElementById('receiptDate').value=d.datum;if(d.totaal!=null&&Number.isFinite(Number(d.totaal)))document.getElementById('receiptTotal').value=Number(d.totaal).toFixed(2);if(d.bonnummer)document.getElementById('receiptNumber').value=String(d.bonnummer);document.getElementById('receiptText').value=receiptJsonToReadable(d);document.getElementById('receiptForm').dataset.receiptJson=JSON.stringify(d);document.getElementById('receiptLinkTx').innerHTML=receiptLinkOptions(document.getElementById('receiptLinkTx').value||'',String(d.datum||dateNow()).slice(0,7));status.innerHTML=`Overgenomen: ${d.producten.length} productregels${d.onzekerheden?.length?`, ${d.onzekerheden.length} aandachtspunt(en)`:''}. Controleer alles voordat je opslaat.`+receiptValidationHtml(d);toast('Bongegevens overgenomen. Controleer de regels en het totaal.')}catch(e){status.textContent=e.message||'JSON kon niet worden verwerkt.';toast(status.textContent,'error')}}
function saveReceiptFromForm(e){e.preventDefault();const form=document.getElementById('receiptForm'),editId=form.dataset.editId||'',store=document.getElementById('receiptStore').value.trim(),date=document.getElementById('receiptDate').value,text=document.getElementById('receiptText').value.trim(),rawTotal=document.getElementById('receiptTotal').value,total=rawTotal===''?null:Number(rawTotal);if(!date||!text){toast('Vul minimaal de datum en bontekst in.','error');return}if(total!==null&&(!Number.isFinite(total)||total<0)){toast('Controleer het totaalbedrag.','error');return}const old=state.receipts.find(r=>r.id===editId);let structured=null;try{const raw=form.dataset.receiptJson;if(raw)structured=JSON.parse(raw)}catch(e){}const obj={id:old?.id||uid(),store,date,total,number:document.getElementById('receiptNumber').value.trim(),text,structured,products:structured?.producten||old?.products||[],transactionId:document.getElementById('receiptLinkTx').value||null,createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};if(old)state.receipts=state.receipts.map(r=>r.id===old.id?obj:r);else state.receipts.push(obj);if(!save())return;form.reset();delete form.dataset.editId;delete form.dataset.receiptJson;document.getElementById('receiptDate').value=selectedMonth+'-01';document.getElementById('receiptImportStatus').textContent='';document.getElementById('receiptImportJson').value='';document.getElementById('receiptText').value='';delete form.dataset.receiptJson;renderReceipts();toast(old?'Bon bijgewerkt.':'Bontekst opgeslagen.');}
function exportReceiptMonth(){const month=receiptMonthValue();const rs=state.receipts.filter(r=>String(r.date||'').startsWith(month)).sort((a,b)=>String(a.date).localeCompare(String(b.date)));if(!rs.length){toast('Geen bonnen in deze maand.','error');return}const out=[`UITGAVENKOMPAS — BONNENBUNDEL ${month}`,`Aantal bonnen: ${rs.length}`,``,...rs.flatMap((r,i)=>[`========== BON ${i+1} ==========`,`Winkel: ${r.store||'Onbekend'}`,`Datum: ${r.date}`,`Totaal: ${r.total==null?'Onbekend':money(r.total)}`,`Bonnummer: ${r.number||'Niet vermeld'}`,`Gekoppelde transactie: ${receiptLinkedTx(r)?`${receiptLinkedTx(r).date} | ${receiptLinkedTx(r).description} | ${money(receiptLinkedTx(r).amount)}`:'Geen'}`,``,r.text||'[Geen bontekst]',r.structured?`\nGEStructureerde JSON:\n${JSON.stringify(r.structured,null,2)}`:'',``])].join('\n');downloadBlob(`uitgavenkompas-bonnen-${month}.txt`,out,'text/plain;charset=utf-8');toast('Maandbundel gedownload.')}
