function exportBackup(){try{if(financeStorageBlocked||!storageGuard)throw Error('Financiële gegevens zijn niet veilig leesbaar.');storageGuard.assertCurrent();downloadBlob(`${demoStateBackup!==null?'memento-demo':'uitgavenkompas'}-backup-${dateNow()}.json`,JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),'application/json');if(demoStateBackup===null){try{localStorage.setItem('memento_last_backup_v1',new Date().toISOString());window.MementoLife?.refreshBackupStatus?.();}catch{}}toast(demoStateBackup!==null?'Demo-export klaargezet. Je eigen gegevens staan hier niet in.':'Financiële JSON klaargezet. Controleer het bestand in je browserdownloads.');}catch(e){toast(e.message||'Exporteren mislukt.','error')}}
