function importBackup(file){const reader=new FileReader();reader.onload=()=>{try{const d=JSON.parse(reader.result);if(!d||!Array.isArray(d.transactions)||!Array.isArray(d.categories))throw new Error('Dit bestand lijkt geen Memento-back-up.');if(!confirm(`Back-up gevonden met ${d.transactions.length} transacties, ${d.bills?.length||0} vaste lasten en ${d.goals?.length||0} spaardoelen. Je huidige gegevens worden overschreven. Doorgaan?`))return;financeStorageBlocked=false;const fresh=emptyState();state={...fresh,...d,settings:{...fresh.settings,...(d.settings||{})},transactions:d.transactions,categories:d.categories.map(c=>({...c,subcategories:Array.isArray(c.subcategories)?c.subcategories:[]})),budgets:d.budgets||{},bills:d.bills||[],goals:d.goals||[],monthClosures:d.monthClosures||{}};if(!state.categories.some(c=>c.name.toLowerCase()==='auto')){const auto=fresh.categories.find(c=>c.name==='Auto');if(auto)state.categories.push({...auto,subcategories:[...(auto.subcategories||[])]})}state.settings.accountOpening={...fresh.settings.accountOpening,...(d.settings?.accountOpening||{})};if(!d.settings?.accountOpening&&Number(d.settings?.startBalance))state.settings.accountOpening.personal=Number(d.settings.startBalance);state.settings.actualBalances={...fresh.settings.actualBalances,...(d.settings?.actualBalances||{})};if(!save())return;renderAll();toast('Back-up hersteld.')}catch(e){toast(e.message||'Back-up niet te lezen.','error')}};reader.readAsText(file)}
function detectDelimiter(line){const opts=[';',',','\t'];return opts.map(d=>({d,n:(line.match(new RegExp(d==='\t'?'\\t':d===';'?'\\;':',','g'))||[]).length})).sort((a,b)=>b.n-a.n)[0].d}
function parseCSVRows(text,delimiter){const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++}else quoted=!quoted}else if(ch===delimiter&&!quoted){row.push(field);field=''}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(v=>v.trim()!==''))rows.push(row);row=[];field=''}else field+=ch}row.push(field);if(row.some(v=>v.trim()!==''))rows.push(row);return rows}
function normaliseHeader(h){return String(h||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'')}
function guessCSVColumn(headers,patterns){return headers.findIndex(h=>patterns.some(p=>normaliseHeader(h).includes(p)))}
function parseCSVDate(v){const s=String(v||'').trim();if(!s)return '';let m=s.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})/);if(m)return `${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`;m=s.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{2,4})$/);if(m){let y=+m[3];if(y<100)y+=y<50?2000:1900;return `${y}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`}const d=new Date(s);return Number.isNaN(d.getTime())?'':isoDate(d)}
function parseCSVAmount(v){let s=String(v??'').trim().replace(/[€$£\s]/g,'');if(!s)return NaN;let neg=false;if(/^\(.*\)$/.test(s)){neg=true;s=s.slice(1,-1)}if(s.startsWith('-'))neg=!neg;s=s.replace(/^[+-]/,'');const comma=s.lastIndexOf(','),dot=s.lastIndexOf('.');if(comma>-1&&dot>-1){if(comma>dot)s=s.replace(/\./g,'').replace(',','.');else s=s.replace(/,/g,'')}else if(comma>-1){const decimals=s.length-comma-1;if(decimals===1||decimals===2)s=s.replace(/\./g,'').replace(',','.');else s=s.replace(/,/g,'')}else if((s.match(/\./g)||[]).length>1){const last=s.lastIndexOf('.');s=s.slice(0,last).replace(/\./g,'')+s.slice(last)}const n=Number(s);return Number.isFinite(n)?(neg?-Math.abs(n):n):NaN}
function readCsvFile(file){const reader=new FileReader();reader.onload=()=>{try{const text=String(reader.result||'').replace(/^\uFEFF/,'');const delimiter=detectDelimiter(text.split(/\r?\n/,1)[0]||';');const rows=parseCSVRows(text,delimiter);if(rows.length<2)throw new Error('Het CSV-bestand bevat geen dataregels.');const headers=rows[0].map((h,i)=>String(h||'').trim()||`Kolom ${i+1}`);openCSVMapping(headers,rows.slice(1).filter(r=>r.some(v=>String(v).trim()!=='')),delimiter,file.name)}catch(err){toast(err.message||'CSV-bestand kan niet worden gelezen.','error')}};reader.readAsText(file)}
function openCSVMapping(headers,rows,delimiter,filename){const options=`<option value="">— Niet aanwezig —</option>`+headers.map((h,i)=>`<option value="${i}">${esc(h)}</option>`).join('');const fields=[['date','Datum *',['datum','date','boekdatum','transactiedatum','valutadatum']],['description','Omschrijving *',['omschrijving','description','naam','details','transactie','mededeling','tegenrekeningnaam']],['amount','Bedrag *',['bedrag','amount','bedragin','bedraguit','mutatie','waarde']],['type','Type',['type','soort','debetcredit','afbij']],['category','Categorie',['categorie','category']],['merchant','Winkel / tegenpartij',['tegenpartij','merchant','begunstigde','naamtegenpartij']],['note','Notitie',['notitie','note','omschrijving2']]];const preselect={};fields.forEach(([id,label,patterns])=>preselect[id]=guessCSVColumn(headers,patterns));if(preselect.date<0)preselect.date=0;if(preselect.description<0)preselect.description=headers.length>1?1:0;if(preselect.amount<0)preselect.amount=headers.length>2?2:headers.length-1;const mapUI=fields.map(([id,label])=>`<div class="form-field"><label for="csv-${id}">${label}</label><select id="csv-${id}">${options}</select></div>`).join('');const importDefaults=`<div class="form-field"><label for="csvAccount">Importeren op rekening</label><select id="csvAccount"><option value="personal">Persoonlijke rekening</option><option value="joint">Gezamenlijke boodschappenrekening</option><option value="creditcard">Creditcard</option></select><small>Geldt voor alle transacties uit dit bestand.</small></div><div class="form-field"><label for="csvPerson">Uitgever / toewijzing</label><select id="csvPerson"><option value="Jari" selected>Jari</option><option value="Daisy">Daisy</option><option value="Jari &amp; Daisy">Jari &amp; Daisy</option></select></div>`;const preview=rows.slice(0,3).map(r=>`<tr>${headers.slice(0,5).map((_,i)=>`<td>${esc(r[i]||'')}</td>`).join('')}</tr>`).join('');const body=`<div class="muted-box" style="margin-bottom:15px"><b style="color:var(--ink)">${esc(filename)}</b><br>${rows.length} dataregels herkend. Scheidingsteken: ${delimiter==='\t'?'tab':delimiter}. Kies de juiste kolommen; er worden nog geen gegevens geïmporteerd.</div><form id="csvMappingForm"><div class="form-grid">${mapUI}${importDefaults}<div class="form-field wide"><label style="display:flex;align-items:center;gap:8px"><input id="csvSkipDuplicates" type="checkbox" checked style="width:auto"> Mogelijke dubbele transacties overslaan</label><small>Dubbel = dezelfde datum, omschrijving, hetzelfde type en hetzelfde bedrag.</small></div></div></form><div class="card-subtitle" style="margin:16px 0 7px">Voorbeeld van de eerste regels</div><div class="table-wrap" style="border:1px solid var(--line);border-radius:10px"><table class="data-table"><tbody>${preview}</tbody></table></div>`;showModal('Bank-CSV importeren','Controleer de kolomkoppeling en importeer daarna.',body,`<button class="btn" type="button" id="cancelCSV">Annuleren</button><button class="btn primary" type="submit" form="csvMappingForm">Importeren</button>`,true);fields.forEach(([id])=>{const el=document.getElementById('csv-'+id);if(preselect[id]>=0)el.value=String(preselect[id])});document.getElementById('cancelCSV').onclick=closeModal;document.getElementById('csvMappingForm').onsubmit=e=>{e.preventDefault();const mapping={};fields.forEach(([id])=>mapping[id]=document.getElementById('csv-'+id).value===''?null:Number(document.getElementById('csv-'+id).value));if(mapping.date===null||mapping.description===null||mapping.amount===null){toast('Koppel minimaal datum, omschrijving en bedrag.','error');return}const skip=document.getElementById('csvSkipDuplicates').checked,importAccount=document.getElementById('csvAccount').value,importPerson=document.getElementById('csvPerson').value;let added=0,duplicates=0,invalid=0;for(const row of rows){const date=parseCSVDate(row[mapping.date]),desc=String(row[mapping.description]||'').trim(),raw=parseCSVAmount(row[mapping.amount]);if(!date||!desc||!Number.isFinite(raw)||raw===0){invalid++;continue}let type='expense';if(mapping.type!==null){const tv=String(row[mapping.type]||'').toLowerCase(),typeHint=tv+' '+desc.toLowerCase();if(/terugbetaling|refund|retour/.test(typeHint))type='refund';else if(/inkom|credit|bijschrijving|storting|salaris|ontvang|bij\b/.test(tv))type='income';else if(/uitgav|debet|afschrij|betaling|af\b|pin/.test(tv))type='expense';else type=raw<0?'expense':'income'}else type=raw<0?'expense':'income';const amount=Math.round(Math.abs(raw)*100)/100;const explicitCategory=mapping.category!==null?String(row[mapping.category]||'').trim():'';const chosen=state.categories.find(c=>c.name.toLowerCase()===explicitCategory.toLowerCase())?.name||(type==='income'?(state.categories.find(c=>/salaris/i.test(desc)&&c.name==='Salaris')?.name||state.categories.find(c=>c.kind==='income')?.name||'Inkomsten'):inferExpenseCategory(desc));const description=desc;const duplicate=state.transactions.some(t=>t.date===date&&Math.abs(+t.amount)===amount&&t.type===type&&(String(t.description||'').toLowerCase().trim()===description.toLowerCase().trim())&&(t.account||'personal')===importAccount&&(t.person||'Jari')===importPerson);if(duplicate&&skip){duplicates++;continue}let note='Geïmporteerd uit CSV';if(mapping.note!==null&&row[mapping.note])note+=' · '+String(row[mapping.note]).trim();state.transactions.push({id:uid(),type,date,description,merchant:mapping.merchant!==null?String(row[mapping.merchant]||'').trim():'',amount,category:chosen,account:importAccount,person:importPerson,splits:null,note,createdAt:new Date().toISOString(),importSource:filename});added++}if(!added){toast(`Geen transacties geïmporteerd. ${invalid} regels ongeldig; ${duplicates} dubbelen overgeslagen.`, 'error');return}if(!save())return;closeModal();renderAll();toast(`${added} transacties geïmporteerd${duplicates?`; ${duplicates} dubbelen overgeslagen`:''}${invalid?`; ${invalid} ongeldige regels overgeslagen`:''}.`)}}
function inferExpenseCategory(desc){const d=desc.toLowerCase();const rules=[['Boodschappen',/albert heijn|jumbo|lidl|aldi|plus|supermarkt|dirk|coop|boodschap/],['Vervoer',/tank|shell|esso|bp |ov-chip|ns |arriva|parkeren|benzine|brandstof/],['Horeca',/restaurant|cafe|café|thuisbezorgd|uber eats|just eat|mcdonald|starbucks|lunch/],['Abonnementen',/netflix|spotify|disney|abonnement|videoland|amazon prime/],['Wonen',/huur|energie|gas|water|elektra|woning/],['Verzekeringen',/verzekering|zorgpremie/],['Gezondheid',/apotheek|huisarts|tandarts|sportschool|gym/],['Winkelen',/bol.com|amazon|zalando|kleding|winkel/]];for(const [name,re] of rules)if(re.test(d)&&state.categories.some(c=>c.name===name))return name;return state.categories.find(c=>c.name==='Overig')?.name||state.categories.find(c=>c.kind!=='income')?.name||'Overig'}
