function researchPanel(){
 const view=document.getElementById('view-smartbuy');if(!view)return;
 if(!document.getElementById('researchWorkspace')){const panel=document.createElement('section');panel.id='researchWorkspace';panel.className='card memento-research-panel';panel.innerHTML='<h2>Onderzoeksdossier</h2><p class="card-subtitle">Bewaar antwoorden, eisen en resultaten bij deze productwens. Onderzoek voer je met de prompt in ChatGPT uit.</p><div class="form-field"><label for="researchAnswers">Mijn antwoorden en eisenprofiel</label><textarea id="researchAnswers" rows="4" maxlength="20000" placeholder="Bewaar hier je antwoorden uit het gesprek en het complete eisenprofiel."></textarea></div><label class="memento-note-check"><input type="checkbox" id="researchApproved"><span>Ik heb het bovenstaande eisenprofiel gecontroleerd en keur het goed voor fase 2.</span></label><div class="form-field"><label for="researchResult">Uitkomst, bronlinks en aandachtspunten</label><textarea id="researchResult" rows="4" maxlength="30000" placeholder="Plak hier de gecontroleerde onderzoeksuitkomst."></textarea></div><div class="smartbuy-actions"><button class="btn primary" type="button" id="researchSave">Dossier bewaren</button><button class="btn" type="button" id="researchNew">Nieuw dossier</button></div><div id="researchSavedList"></div>';view.append(panel);document.getElementById('researchSave').onclick=()=>saveResearch();document.getElementById('researchNew').onclick=()=>{activeResearchId='';activeResearchWish='';activeResearchPurchase='';document.getElementById('smartBuyForm').reset();document.getElementById('researchAnswers').value='';document.getElementById('researchResult').value='';document.getElementById('researchApproved').checked=false;document.getElementById('smartBuyOutputCard').hidden=true};['smartBuyProduct','smartBuyBudget','smartBuyPreferences','smartBuyExclude','researchAnswers'].forEach(id=>document.getElementById(id).addEventListener('input',()=>{document.getElementById('researchApproved').checked=false}));panel.addEventListener('click',e=>{const load=e.target.closest('[data-research-load]');if(load)loadResearch(load.dataset.researchLoad);const del=e.target.closest('[data-research-delete]');if(del){const r=(state.research||[]).find(x=>x.id===del.dataset.researchDelete);if(r&&confirm('Onderzoeksdossier naar de prullenbak?')){if(!softDeleteFinance('research',r.id))return;if(activeResearchId===r.id)activeResearchId='';researchPanel()}}})}
 let context=document.getElementById('researchSourceContext');if(!context){context=document.createElement('div');context.id='researchSourceContext';context.className='smartbuy-actions';document.getElementById('researchWorkspace').prepend(context);}context.innerHTML=(activeResearchWish?'<button type="button" class="btn" id="researchBackWish">Terug naar aankoopwens</button>':'')+'<button type="button" class="btn" id="researchRegisterExpense">Uitgave apart registreren</button>';
 if(activeResearchWish)document.getElementById('researchBackWish').onclick=()=>window.MementoLife?.openWish?.(activeResearchWish);
 document.getElementById('researchRegisterExpense').onclick=()=>transactionModal(null,{description:document.getElementById('smartBuyProduct').value.trim(),note:activeResearchId?'Onderzoeksdossier: '+activeResearchId:''});
 const list=document.getElementById('researchSavedList');list.innerHTML='<h3>Bewaarde onderzoeken</h3>'+((state.research||[]).length?state.research.map(r=>'<div class="setting-row"><div><b>'+esc(r.product)+'</b><span>'+esc(r.result?'Uitkomst bewaard':r.approved?'Eisenprofiel goedgekeurd':'Fase 1 · wensen verduidelijken')+'</span></div><div class="smartbuy-actions"><button type="button" class="btn sm" data-research-load="'+esc(r.id)+'">Open</button><button type="button" class="btn sm danger" data-research-delete="'+esc(r.id)+'">Verwijderen</button></div></div>').join(''):'<p class="card-subtitle">Nog geen onderzoeksdossiers bewaard.</p>');
}
function saveResearch(quiet=false){
 researchPanel();const product=document.getElementById('smartBuyProduct').value.trim();if(!product){toast('Vul eerst een product in.','error');return false}
 state.research=state.research||[];const old=state.research.find(x=>x.id===activeResearchId);
 const r={...(old||{}),id:old?.id||uid(),wishId:activeResearchWish||old?.wishId||'',purchaseId:activeResearchPurchase||old?.purchaseId||'',product,budget:document.getElementById('smartBuyBudget').value,goal:document.getElementById('smartBuyGoal').value,preferences:document.getElementById('smartBuyPreferences').value,exclude:document.getElementById('smartBuyExclude').value,answers:document.getElementById('researchAnswers').value,approved:document.getElementById('researchApproved').checked,result:document.getElementById('researchResult').value,updatedAt:new Date().toISOString()};
 if(r.approved&&!r.answers.trim()){toast('Vul eerst het eisenprofiel in voordat je het goedkeurt.','error');return false}
 if(old)state.research[state.research.indexOf(old)]=r;else state.research.push(r);if(!save())return false;activeResearchId=r.id;if(r.wishId&&window.MementoLife?.linkResearch?.(r.wishId,r.id,r.result)===false){toast('Dossier bewaard; de koppeling kon nog niet worden opgeslagen. Probeer Dossier bewaren opnieuw.','error');return false}if(r.purchaseId&&window.MementoLife?.linkPurchaseResearch?.(r.purchaseId,r.id,r.result)===false){toast('Dossier bewaard; probeer de productkoppeling opnieuw op te slaan.','error');return false}researchPanel();if(!quiet)toast('Onderzoeksdossier lokaal bewaard.');return true;
}
function loadResearch(id){const r=(state.research||[]).find(x=>x.id===id);if(!r)return;researchPanel();activeResearchId=id;activeResearchWish=r.wishId||'';activeResearchPurchase=r.purchaseId||'';for(const [field,value]of Object.entries({smartBuyProduct:r.product,smartBuyBudget:r.budget,smartBuyGoal:r.goal,smartBuyPreferences:r.preferences,smartBuyExclude:r.exclude,researchAnswers:r.answers,researchResult:r.result}))document.getElementById(field).value=value||'';document.getElementById('researchApproved').checked=Boolean(r.approved);document.getElementById('smartBuyOutputCard').hidden=true;researchPanel()}
window.MementoResearch={fromPurchase(id,data){researchPanel();activeResearchWish='';activeResearchPurchase=id;const r=(state.research||[]).find(x=>x.purchaseId===id);if(r)loadResearch(r.id);else{activeResearchId='';document.getElementById('smartBuyForm').reset();for(const [field,value]of Object.entries({smartBuyProduct:data.product,smartBuyBudget:data.budget,smartBuyPreferences:data.preferences,smartBuyExclude:'',researchAnswers:'',researchResult:''}))document.getElementById(field).value=value??'';document.getElementById('researchApproved').checked=false}document.getElementById('smartBuyOutputCard').hidden=true;document.getElementById('smartBuyPrompt').value=''},fromWish(id){researchPanel();activeResearchPurchase='';activeResearchWish=id;let r=(state.research||[]).find(x=>x.wishId===id);const deleted=(state.trash?.research||[]).find(x=>x.item.wishId===id);if(!r&&deleted){if(!confirm('Het gekoppelde onderzoeksdossier staat in de prullenbak. Herstellen en hetzelfde dossier openen?')){activeResearchWish='';toast('Dossier blijft in de prullenbak. De verwijzing is behouden.');return false}restoreFinance('research',deleted.id);r=(state.research||[]).find(x=>x.id===deleted.item.id);if(!r)return false}if(r)loadResearch(r.id);else{activeResearchId='';document.getElementById('researchAnswers').value='';document.getElementById('researchResult').value='';document.getElementById('researchApproved').checked=false}}};
function categoryEditor(index){
 const c=state.categories[index];if(!c)return;const original=c.name;
 showModal('Categorie bewerken','Bestaande transacties en maandbudgetten behouden hun koppeling.',`<form id="categoryEditorForm"><div class="form-field"><label for="categoryEditorName">Naam</label><input id="categoryEditorName" required maxlength="100" value="${esc(c.name)}"></div><div class="form-field"><label for="categoryEditorSubs">Subcategorieën (één per regel)</label><textarea id="categoryEditorSubs" rows="8" maxlength="10000">${esc((c.subcategories||[]).join('\n'))}</textarea><small>Verwijderde subcategorieën blijven op bestaande transacties staan.</small></div></form>`,`<button type="button" class="btn" id="cancelCategoryEditor">Annuleren</button><button class="btn primary" form="categoryEditorForm">Opslaan</button>`);
 document.getElementById('cancelCategoryEditor').onclick=closeModal;
 document.getElementById('categoryEditorForm').onsubmit=e=>{e.preventDefault();const name=document.getElementById('categoryEditorName').value.trim(),subs=document.getElementById('categoryEditorSubs').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(!name||state.categories.some((x,i)=>i!==index&&x.name.toLowerCase()===name.toLowerCase())){toast('Kies een unieke categorienaam.','error');return}const removed=(c.subcategories||[]).filter(x=>!subs.some(s=>s.toLowerCase()===x.toLowerCase()));
const affected=window.MementoCategoryIntegrity.affectedByRemoval(state.transactions,original,removed);
if(affected){toast(affected+' transacties gebruiken een verwijderde subcategorie. Pas die eerst aan.','error');return}
c.name=name;c.subcategories=[...new Map(subs.map(x=>[x.toLowerCase(),x])).values()];if(name!==original){state.transactions.forEach(t=>{if(t.category===original)t.category=name;(t.splits||[]).forEach(p=>{if(p.category===original)p.category=name})});state.bills.forEach(b=>{if(b.category===original)b.category=name});if(state.budgets[original]!==undefined){state.budgets[name]=state.budgets[original];delete state.budgets[original]}Object.values(state.budgetMonths||{}).forEach(month=>Object.values(month).forEach(r=>{if(r.categories?.[original]!==undefined){r.categories[name]=r.categories[original];delete r.categories[original]}}))}if(!save())return;closeModal();renderSettings();toast('Categorie bijgewerkt.')};
}

function buildSmartBuyPrompt(){
 const product=document.getElementById('smartBuyProduct').value.trim();
 const budget=document.getElementById('smartBuyBudget').value.trim();
 const goal=document.getElementById('smartBuyGoal').value;
 const prefs=document.getElementById('smartBuyPreferences').value.trim();
 const exclude=document.getElementById('smartBuyExclude').value.trim();
 if(!product){toast('Vul eerst in wat je zoekt.','error');return ''}
 const modes={
  budget:{label:'Goedkoopste geschikte optie',rule:'Pas eerst de minimale eisen toe. Kies daarna de goedkoopste aantoonbaar geschikte kandidaat; een lage prijs compenseert geen essentiële tekortkoming.'},
  value:{label:'Beste prijs-kwaliteit',rule:'Kies de kandidaat waarvan aantoonbare praktische voordelen de prijs het best rechtvaardigen. Zoek actief naar een goedkoper model dat vrijwel hetzelfde biedt.'},
  premium:{label:'Beste kwaliteit, prijs minder belangrijk',rule:'Geef prioriteit aan aantoonbare prestaties, betrouwbaarheid en gebruiksgemak. Leg uit wat de meerprijs concreet oplevert en wanneer die niet gerechtvaardigd is.'},
  multiple:{label:'Meerdere opties vergelijken',rule:'Bepaal afzonderlijk de goedkoopste geschikte keuze, beste prijs-kwaliteitkeuze en beste premiumkeuze binnen het opgegeven budget, tenzij ik expliciet om opties boven budget vraag. Eén kandidaat mag meerdere titels krijgen. De top 3 is een maximum, geen verplichting; forceer geen winnaar als bewijs ontbreekt.'}
 };
 const mode=modes[goal]||modes.budget;
 const budgetText=budget||'Niet opgegeven; bepaal relevante prijsklassen en leg kort uit wat extra betalen oplevert.';
 const budgetRule=budget
  ? 'Het opgegeven budget is een harde bovengrens voor de longlist en alle aanbevelingen, inclusief verplichte verzendkosten waar bekend. Neem geen producten boven deze grens op, ook niet als referentie of premiumvergelijking. Als er geen geschikte premiumoptie binnen budget bestaat, zeg dat eerlijk; vraag toestemming voordat je buiten-budgetalternatieven onderzoekt.'
  : 'Budget ontbreekt. Vergelijk relevante prijsklassen en maak duidelijk wat extra betalen oplevert; verzin geen budget.';
 const outputRule=goal==='multiple'
  ? 'Geef: A) kort advies in maximaal 3–5 zinnen; B) een longlisttabel met als doel 10 concrete kandidaten (streef naar 10, maximaal 10; zie de uitzondering hieronder); C) een topvergelijking van maximaal 3 kandidaten; D) een kort eindoordeel met goedkoopste geschikte, prijs-kwaliteit en premium binnen budget; E) alleen de belangrijkste bronnen en onzekerheden.'
  : 'Geef: A) kort advies in maximaal 3–5 zinnen; B) een longlisttabel met als doel 10 concrete kandidaten (streef naar 10, maximaal 10; zie de uitzondering hieronder); C) een vergelijking van maximaal 3 kandidaten; D) een beknopt eindoordeel; E) alleen de belangrijkste bronnen en onzekerheden.';
 return `# Slim Kopen — onafhankelijk aankooponderzoek

## Mijn ingevulde gegevens
- Product: ${product}
- Budget: ${budgetText}
- Adviesvorm: ${mode.label}
- Prioriteit: ${mode.rule}
- Voorkeuren die ik al heb opgegeven: ${prefs||'Niet opgegeven.'}
- Uitsluiten: ${exclude||'Niet opgegeven.'}
- Markt: Nederland; gebruik actuele informatie als webtoegang beschikbaar is.

## Verplicht proces in twee fasen
Werk in twee duidelijk gescheiden fasen. **Fase 1 is het gesprek met mij om mijn behoeften te begrijpen. Fase 2 is het daadwerkelijke brede marktonderzoek. Begin fase 2 nooit voordat ik het eisenprofiel expliciet heb goedgekeurd.** Als ik nog geen akkoord heb gegeven, is je volledige antwoord uitsluitend gericht op de verheldering en goedkeuring van mijn wensen; zoek of rangschik dan nog geen concrete producten.

# Fase 1 — adaptief behoefteonderzoek

## 1. Gebruik de bekende informatie
Begin met de gegevens hierboven. Vraag niet opnieuw naar iets dat ik al heb ingevuld of duidelijk beantwoord. Leid niet meer af dan mijn antwoorden rechtvaardigen. Als een essentieel gegeven ontbreekt, vraag ernaar.

## 2. Houd een actueel overzicht bij en voorkom herhaling
Behandel alle berichten in deze conversatie als één doorlopend behoefteonderzoek. Bij elke beurt moet je eerst de volledige eerdere conversatie nalopen en je bestaande overzicht bijwerken voordat je een nieuwe vraag kiest. Verlies eerder gegeven informatie niet omdat die in een ander bericht, als opsomming of als antwoord op een andere vraag stond.

Houd tijdens fase 1 een intern, bijgewerkt overzicht bij van:
- **Bekend en bevestigd:** feiten en voorkeuren die ik al heb genoemd.
- **Besloten prioriteiten:** keuzes die ik al heb gemaakt tussen functies, prijs en compromissen.
- **Open vragen:** alleen onzekerheden die de geschiktheid, selectie, prijs of rangschikking wezenlijk kunnen veranderen.
- **Nog niet besproken opties:** relevante functies die mogelijk belangrijk zijn, maar waarover ik nog geen keuze heb gemaakt.

Dit overzicht is een hulpmiddel om vragen te kiezen, geen reden om bij iedere beurt alles opnieuw op te sommen. Toon het volledige overzicht pas in het eisenprofiel ter goedkeuring.

**Anti-dubbelvraagregel:**
- Vraag nooit opnieuw naar iets dat al duidelijk is beantwoord, ook niet met andere woorden of in een andere volgorde.
- Behandel een antwoord als bekend wanneer ik het rechtstreeks heb genoemd of wanneer mijn keuze ondubbelzinnig uit mijn eerdere antwoorden volgt.
- Stel alleen een verduidelijkingsvraag als eerdere antwoorden elkaar tegenspreken, een essentieel detail echt onduidelijk blijft of een nieuwe afweging ontstaat die nog niet is beantwoord.
- Vraag niet opnieuw naar budget, vloertype, woninggrootte, navigatie, obstakelherkenning, dweilwensen, onderhoud of basisstationruimte als die informatie al beschikbaar is.
- Als je merkt dat je op het punt staat een eerdere vraag te herhalen, sla die over en kies de belangrijkste nog openstaande vraag.
- Vraag in elke beurt alleen naar de **volgende meest relevante open onzekerheid**. Noem kort waarom die vraag belangrijk is, zonder eerdere antwoorden opnieuw uit te vragen.

## 3. Stel relevante vervolgvragen
Voer een adaptief gesprek. Stel vragen die passen bij de productcategorie, mijn antwoorden, budget en gebruikssituatie. Er is geen star maximum aan het aantal vragen: stel gerust meerdere vragenrondes als dat de kans op een passende aankoop wezenlijk vergroot. Vraag echter niet door om het doorvragen zelf.

- Begin met de vragen die de geschiktheid of de shortlist het meest kunnen veranderen: gebruikssituatie, frequentie, omgeving, beperkingen, noodzakelijke functies en belangrijkste frustraties.
- Vraag vervolgens naar relevante productfuncties die ik mogelijk nog niet ken. Kies die functies op basis van de productcategorie en mijn antwoorden; gebruik geen generieke, identieke checklist voor elk product.
- Stel bij voorkeur één duidelijke vraag tegelijk, of combineer hooguit enkele nauw verwante vragen als dat voor mij makkelijker is.
- Leg technische termen in gewone taal uit. Vraag niet alleen welke functies ik wil, maar help me begrijpen welke functies voor mijn gebruik relevant kunnen zijn.
- Vermijd dubbele vragen en herhaal mijn eerdere antwoorden niet. Gebruik mijn antwoorden om de volgende vraag te kiezen.
- Geef bij een belangrijke functie waar nodig een korte, neutrale uitleg van de praktische meerwaarde, nadelen en mogelijke meerprijs voordat je mij vraagt hoe belangrijk die functie voor mij is.
- Als ik niet weet wat ik nodig heb, bied dan een korte vergelijking of begrijpelijke voorbeelden aan. Laat mij kiezen tussen harde eis, voorkeur, optioneel of niet nodig; bepaal dat niet stilzwijgend namens mij.
- Vraag naar budgetnuance als die van invloed is: is het budget absoluut, of zou ik alleen voor een aantoonbaar waardevolle functie iets meer willen uitgeven? Verander mijn opgegeven harde budget niet zonder toestemming.
- Vraag naar uitsluitingen, onderhoud, formaat, compatibiliteit, garantie, gebruiksgemak of andere aspecten alleen als ze voor deze categorie relevant zijn.
- Als een antwoord een wezenlijk nieuwe onzekerheid oproept, vraag daar dan op door. Als een detail weinig invloed heeft, benoem zo nodig een aanname in het uiteindelijke profiel in plaats van een nieuwe vraagronde te starten.
- **Controle vóór verzenden:** vergelijk de voorgenomen vraag met het overzicht én met alle eerdere vragen en antwoorden. Controleer of de gebruiker dit al direct of indirect heeft beantwoord. Zo ja, stel die vraag niet; kies een andere open onzekerheid. Als er geen belangrijke open onzekerheden meer zijn, stel dan geen extra vraag maar maak het eisenprofiel ter goedkeuring.

## 4. Verken functies zonder het volledige marktonderzoek te starten
In deze fase mag je algemene productkennis gebruiken om functies, afwegingen en relevante criteria uit te leggen. Als ik niet weet of een functie de meerprijs waard is, help me dan de praktische voor- en nadelen te begrijpen. Je mag een beperkte, gerichte verkenning doen naar de betekenis van een technische functie als dat nodig is om mij een geïnformeerde keuze te laten maken, maar begin nog niet met het zoeken, vergelijken of rangschikken van concrete productkandidaten en doe niet alsof je al een marktonderzoek hebt uitgevoerd. Maak onderscheid tussen algemene uitleg en geverifieerde informatie.

## 5. Bepaal wanneer er genoeg informatie is
Ga door met vragen totdat de belangrijke onzekerheden over geschiktheid, essentiële functies en belangrijke afwegingen voldoende zijn opgelost. Stop niet alleen omdat er een bepaald aantal vragen is gesteld. Stop ook niet met doorvragen als een belangrijke keuze nog onduidelijk is. Vraag niet naar details die waarschijnlijk geen invloed hebben op de aankoopbeslissing.

## 6. Presenteer het eisenprofiel ter goedkeuring
Zodra de behoeften voldoende duidelijk zijn, geef je een beknopt maar concreet overzicht met:
- **Harde eisen:** voorwaarden waaraan een kandidaat moet voldoen om mee te doen.
- **Belangrijke voorkeuren:** functies die de voorkeur hebben, maar niet automatisch verplicht zijn.
- **Optionele extra's:** functies die prettig kunnen zijn, afhankelijk van prijs en bewezen nut.
- **Niet nodig / uitsluiten:** functies, typen producten of compromissen die ik niet wil.
- **Gebruikssituatie en randvoorwaarden:** relevante omgeving, frequentie, compatibiliteit, formaat en andere omstandigheden.
- **Budget en prijsafweging:** harde bovengrens, gewenste prijsklasse en eventuele ruimte voor een meerprijs die ik uitdrukkelijk heb toegestaan.
- **Openstaande onzekerheden of aannames:** alleen wat nog relevant is en hoe dat de selectie kan beïnvloeden.

Leg uit welke eisen het aanbod mogelijk sterk beperken. Maak duidelijk welke functies je als harde eis hebt genoteerd en welke slechts voorkeur zijn. Verander mijn voorkeuren niet stilzwijgend in harde eisen.

Sluit af met de vraag of ik dit eisenprofiel goedkeur of wil aanpassen. **Start het productonderzoek pas na een expliciet akkoord van mij.** Een stilzwijgende reactie, nieuwe vraag of alleen een productvoorkeur is geen akkoord. Als ik wijzigingen vraag, pas je het profiel aan en vraag je opnieuw om goedkeuring.

# Fase 2 — breed, zorgvuldig marktonderzoek
Voer deze fase pas uit nadat ik het eisenprofiel expliciet heb goedgekeurd. Gebruik het goedgekeurde profiel als toetsingskader. Als ik later een harde eis of het budget wijzig, bevestig dan de gewijzigde eisen voordat je verdergaat als die de onderzoeksrichting wezenlijk veranderen.

## Onderzoeksopdracht — neem voldoende tijd en stop niet na een paar zoekresultaten
Voer eerst het onderzoek uit en schrijf pas daarna het eindantwoord. Geef geen snelle eerste indruk alsof die een marktonderzoek is. Laat geen verborgen redeneerstappen of interne denkmonoloog zien; toon wel concrete zoekdekking, gecontroleerde feiten, bronlinks, onzekerheden en de reden voor de uiteindelijke selectie. Gebruik webtoegang actief als die beschikbaar is. Als webtoegang niet beschikbaar is, claim dan niet dat je uitgebreid of actueel marktonderzoek hebt gedaan.

1. **Bepaal de maatstaf.** Vertaal het goedgekeurde profiel naar toetsbare eisen, voorkeuren en dealbreakers. Pas harde eisen toe vóór rangschikking.
2. **Doe een brede marktverkenning in meerdere rondes.** Begin niet meteen met de eerste twee bekende producten. Zoek in ten minste drie afzonderlijke zoekrondes met verschillende invalshoeken: (a) categorie- en modeloverzichten, (b) concrete modellen van verschillende merken, (c) actuele Nederlandse winkel- en prijsresultaten en alternatieven van concurrenten. Zoek waar passend bij minimaal 5 verschillende merken en 5 verschillende winkels of onafhankelijke bronnen. Gebruik meerdere relevante zoektermen en synoniemen. Houd een kandidatenlijst bij en dedupliceer exact dezelfde uitvoering. Zoek na de eerste kandidaten expliciet verder naar ontbrekende merken, goedkopere alternatieven en modellen met andere afwegingen.
3. **Aantal kandidaten is een expliciete eis.** Streef naar 10 verschillende, concrete productmodellen in de longlist en toon normaal gesproken 8–10 kandidaten. Twee of drie kandidaten is voor een brede productcategorie onvoldoende. Toon minder dan 8 uitsluitend wanneer de markt aantoonbaar klein is of de goedgekeurde harde eisen/budget de keuze echt beperken. Vermeld dan welke extra zoekrichtingen, merken of winkels je hebt onderzocht en waarom die geen extra geschikte kandidaat opleverden. Gebrek aan onafhankelijke tests is op zichzelf geen reden om een plausibel geschikte kandidaat weg te laten; label de bewijsbeperking.
4. **Houd je aan het budget.** Maak een longlist van maximaal 10 concrete, plausibel geschikte producten die binnen het goedgekeurde budget passen. ${budgetRule} Vul de lijst niet met ongeschikte producten, duplicaten, kleurvarianten of modellen boven budget.
5. **Controleer elke kandidaat.** Open waar mogelijk de directe productpagina. Controleer exact model/variant, prijs, verkoper, verzendkosten, beschikbaarheid en controledatum. Link bij elk product naar de exacte productpagina, niet alleen naar een merkpagina, zoekresultaat of algemene categorie. Als prijzen botsen, onderzoek het verschil. Blijft het onduidelijk, label het als onzeker en behandel het niet als bevestigd. Een niet-toegankelijke pagina bewijst geen actuele prijs of voorraad. Gebruik prijsvergelijkers om aanbiedingen te vinden, maar controleer de uiteindelijke prijs liefst bij de verkoper.
6. **Gebruik bewijs passend bij de claim.** Fabrikant/winkel voor specificaties en voorwaarden; onafhankelijke tests voor prestaties; gebruikerservaringen voor terugkerende praktijkproblemen. Geef de voorkeur aan vergelijkende tests met dezelfde meetmethode. Zoek actief naar nadelen en tegenbewijs. Marketingclaims, losse reviews en hoge scores zijn op zichzelf geen onafhankelijk bewijs.
7. **Vergelijk eerlijk.** Gebruik dezelfde relevante criteria voor alle kandidaten. Vertaal specificaties naar praktische gevolgen. Vergelijk getallen alleen als varianten, meetmethoden en omstandigheden voldoende overeenkomen. Markeer ontbrekende informatie als ‘onbekend’; interpreteer die niet automatisch positief of negatief. Maak onderscheid tussen specificaties en bewezen praktijkprestaties.
8. **Selecteer en weerleg.** Rangschik pas nadat de brede zoekronde is afgerond. Geef kort aan waarom relevante kandidaten afvallen. Selecteer maximaal drie best onderbouwde opties. Zoek voor de voorlopige nummer 1 naar een goedkoper gelijkwaardig alternatief en naar de sterkste reden om hem niet te kiezen. Een derde optie is niet verplicht als het bewijs onvoldoende is. Ken geen titel toe die de gegevens niet ondersteunen.
9. **Controleer de uitkomst.** Controleer modelnummers, links, prijzen, claims en berekeningen op consistentie. Gebruik dezelfde gecontroleerde prijs overal. Vermeld totale gebruikskosten alleen als gegevens beschikbaar zijn; toon aannames en verzin geen levensduur of kosten.
10. **Wees transparant over zekerheid.** Maak onderscheid tussen bevestigd feit, claim van fabrikant/winkel, gebruikerservaring en eigen beoordeling. Verlaag de zekerheid als onafhankelijke tests ontbreken of bronnen niet vergelijkbaar zijn. Geen verzonnen scores, specificaties, tests, prijzen, voorraad of links. Als actuele webtoegang ontbreekt, zeg dat en presenteer prijzen/voorraad niet als live geverifieerd.

## Gewenste eindantwoord
${outputRule}

Voor de longlist: houd de tabel scanbaar. Gebruik waar relevant de kolommen exacte product/variant, gecontroleerde prijs inclusief verzending indien bekend, 2–4 doorslaggevende kenmerken, grootste plus, grootste min, bewijsstatus en directe link naar de exacte productpagina. Elke rij moet een klikbare, concrete productlink bevatten. Als de prijs niet rechtstreeks is gecontroleerd, schrijf ‘indicatief — niet bevestigd’ en benoem de bron; noem hem niet ‘gecontroleerd’. Vermeld aan het begin van de tabel hoeveel verschillende modellen daadwerkelijk zijn onderzocht en hoeveel er in de tabel staan.

Voor de topvergelijking: toon alleen kenmerken en testresultaten die de keuze echt veranderen. Vermeld het prijsverschil en wat de meerprijs concreet oplevert. Zeg wanneer een goedkoper product vrijwel hetzelfde biedt. Baseer de rangschikking op geverifieerde geschiktheid en bewijs, niet op één opgegeven specificatie of fabrikantclaim.

## Eindregels
Houd het eindantwoord beknopt en aankoopgericht, maar bezuinig niet op de onderzoeksfase om snel te antwoorden. Stop niet na twee geschikte producten of na de eerste zoekpagina. Het marktonderzoek erachter moet breed en zorgvuldig zijn. Besteed de inspanning aan meerdere zoekrondes, het vinden van alternatieven, het verifiëren en het testen van de voorlopige conclusie; toon alleen bevindingen die mijn beslissing helpen. Als directe productlinks, actuele prijzen of voldoende onafhankelijke tests ontbreken, zeg dat expliciet en verlaag de zekerheid. Bevestig vóór aankoop altijd de uiteindelijke prijs, uitvoering en beschikbaarheid op de winkelpagina.`;
}
