// Opt-in manual privacy lock. Existing PIN hashes remain untouched; no idle/autolock.
const PIN_MANUAL_ONLY=document.documentElement?.dataset?.mementoPinLock==='manual';
const PIN_LOCK_ENABLED=document.documentElement?.dataset?.mementoPinLock!=='disabled';
const PIN_MANUAL_KEY='memento_manual_pin_lock_v1';
const PIN_CONFIG_KEY='uitgavenkompas_pin_config_v1';
const PIN_TIMEOUT_KEY='memento_pin_autolock_minutes_v1';
const PIN_SESSION_KEY='memento_pin_temporary_session_v1';
const PIN_ALLOWED_MINUTES=[1,5,15,30];
let pinUnlocked=!PIN_LOCK_ENABLED,pinFailures=0,pinIdleTimer=null,pinLastActivity=0;
function getPinTimeoutMinutes(){
 try{const minutes=Number(localStorage.getItem(PIN_TIMEOUT_KEY));return PIN_ALLOWED_MINUTES.includes(minutes)?minutes:15}catch(_){return 15}
}
function pinSavedSession(){
 try{const data=JSON.parse(sessionStorage.getItem(PIN_SESSION_KEY)||'null');return data&&data.version===1?data:null}catch(_){return null}
}
function pinRememberSession(){
 if(PIN_MANUAL_ONLY)return;
 try{const config=JSON.parse(localStorage.getItem(PIN_CONFIG_KEY)||'null');
  if(config?.salt&&pinLastActivity)sessionStorage.setItem(PIN_SESSION_KEY,JSON.stringify({version:1,salt:config.salt,lastActivity:pinLastActivity}));
 }catch(_){} // Browser may block sessionStorage for locally opened files.
}
function pinForgetSession(){try{sessionStorage.removeItem(PIN_SESSION_KEY)}catch(_){}}
function pinLockVisible(){
 if(!PIN_LOCK_ENABLED)return;
 window.MementoStart?.showPin?.();
 document.getElementById('pinLock').classList.add('visible');document.body.classList.add('pin-locked');
 document.getElementById('pinInput').value='';document.getElementById('pinError').textContent='';
 if(!document.hidden)setTimeout(()=>{if(!document.hidden&&!pinUnlocked)document.getElementById('pinInput').focus()},60)
}
function pinHideLock(){
 window.MementoStart?.leave?.();
 document.getElementById('pinLock').classList.remove('visible');document.body.classList.remove('pin-locked');
 document.getElementById('pinInput').value='';document.getElementById('pinError').textContent='';
}
function pinLockNow(){
 if(!PIN_LOCK_ENABLED)return;
 if(PIN_MANUAL_ONLY){
  try{
   if(!localStorage.getItem(PIN_CONFIG_KEY)){
    // No PIN has been configured: ask for a new one, but do not record a locked state yet.
    const f=document.getElementById('pinForm');delete f.dataset.confirm;delete f.dataset.firstPin;
    document.getElementById('pinDescription').textContent='Kies een zescijferige pincode om Memento handmatig te vergrendelen.';
    document.getElementById('pinSubmit').textContent='Pincode instellen';
    document.getElementById('pinError').textContent='';
    pinLockVisible();updatePinSecurityControls();return;
   }
   localStorage.setItem(PIN_MANUAL_KEY,'1');
  }catch{
   document.getElementById('pinError').textContent='Vergrendelen niet mogelijk: lokale opslag is niet beschikbaar.';
   return;
  }
 }
 clearTimeout(pinIdleTimer);pinIdleTimer=null;pinUnlocked=false;pinLastActivity=0;pinForgetSession();
 pinLockVisible();
 updatePinSecurityControls();
}
function pinDeadline(){return pinLastActivity+getPinTimeoutMinutes()*60000}
function pinCheckExpiry(){
 if(PIN_MANUAL_ONLY)return pinUnlocked;
 if(!PIN_LOCK_ENABLED)return true;
 if(!pinUnlocked)return false;
 if(!pinLastActivity||Date.now()>=pinDeadline()){pinLockNow();return false}
 return true
}
function resetPinIdleTimer(updateActivity=true){
 clearTimeout(pinIdleTimer);pinIdleTimer=null;
 if(PIN_MANUAL_ONLY)return;
 if(!PIN_LOCK_ENABLED)return;
 if(!pinUnlocked)return;
 if(updateActivity){
  if(document.hidden)return; // No extending the session while another app is open.
  pinLastActivity=Date.now();pinRememberSession()
 }
 if(!pinCheckExpiry())return;
 const remaining=Math.max(1,pinDeadline()-Date.now());
 pinIdleTimer=setTimeout(()=>{if(pinCheckExpiry())resetPinIdleTimer(false)},remaining);
 updatePinSecurityControls()
}
function pinUnlock(){
 if(PIN_MANUAL_ONLY){try{localStorage.removeItem(PIN_MANUAL_KEY)}catch{document.getElementById('pinError').textContent='Ontgrendelen kan niet worden opgeslagen.';return}}
 pinUnlocked=true;pinHideLock();
 pinLastActivity=Date.now();pinRememberSession();resetPinIdleTimer(false)
}
function pinRestoreRecentSession(config){
 if(PIN_MANUAL_ONLY)return false;
 if(!config)return false;
 try{
  const data=pinSavedSession();const expected=JSON.parse(config);
  if(!data||!expected?.salt||data.salt!==expected.salt||!Number.isFinite(data.lastActivity))return false;
  const age=Date.now()-data.lastActivity;
  if(age<0||age>=getPinTimeoutMinutes()*60000)return false;
  pinUnlocked=true;pinLastActivity=data.lastActivity;pinHideLock();resetPinIdleTimer(false);
  return true
 }catch(_){return false}
}
function updatePinSecurityControls(){
 if(PIN_MANUAL_ONLY){document.querySelectorAll('[data-memento-pin-status]').forEach(el=>{el.textContent=pinUnlocked?(localStorage.getItem(PIN_CONFIG_KEY)?'Ontgrendeld · handmatig vergrendelen':'Ontgrendeld · pincode nog instellen'):'Handmatig vergrendeld'});return;}
 if(!PIN_LOCK_ENABLED){
  document.querySelectorAll('[data-memento-pin-status]').forEach(status=>{status.textContent='Pincodescherm uitgeschakeld'});
  return;
 }
 const minutes=getPinTimeoutMinutes();
 document.querySelectorAll('[data-memento-pin-timeout]').forEach(input=>{if(input.value!==String(minutes))input.value=String(minutes)});
 document.querySelectorAll('[data-memento-pin-status]').forEach(status=>{status.textContent=pinUnlocked?'Ontgrendeld · '+minutes+' minuten':'Vergrendeld'})
}
function setupPinSecurityControls(){
 // Event delegation works with both static Finance and dynamically rendered Leven settings.
 document.addEventListener('change',event=>{
  const input=event.target.closest('[data-memento-pin-timeout]');if(!input)return;
  const minutes=Number(input.value);if(!PIN_ALLOWED_MINUTES.includes(minutes))return;
  try{localStorage.setItem(PIN_TIMEOUT_KEY,String(minutes))}catch(_){return}
  if(pinUnlocked)resetPinIdleTimer(false);else updatePinSecurityControls();
 });
 document.addEventListener('click',event=>{
  if(event.target.closest('[data-memento-pin-lock-now]')){event.preventDefault();pinLockNow()}
 });
 // Reconnect the displayed select to the single saved setting when a life view is re-rendered.
 new MutationObserver(()=>{
  const els=document.querySelectorAll('[data-memento-pin-timeout]');
  if(els.length)updatePinSecurityControls()
 }).observe(document.getElementById('lifeContent'),{childList:true});
}
async function pinDigest(pin,salt){const bytes=new TextEncoder().encode(salt+':'+pin);const hash=await crypto.subtle.digest('SHA-256',bytes);return Array.from(new Uint8Array(hash),b=>b.toString(16).padStart(2,'0')).join('')}
async function initPinLock(){
 if(!PIN_LOCK_ENABLED){pinUnlocked=true;pinHideLock();updatePinSecurityControls();return;}
let config=null;try{config=localStorage.getItem(PIN_CONFIG_KEY)}catch{}
const form=document.getElementById('pinForm'),input=document.getElementById('pinInput'),error=document.getElementById('pinError'),description=document.getElementById('pinDescription'),submit=document.getElementById('pinSubmit');
form.addEventListener('submit',async e=>{
 e.preventDefault();const pin=input.value;
 if(!/^\d{6}$/.test(pin)){error.textContent='Voer precies 6 cijfers in.';return}
 const current=JSON.parse(localStorage.getItem(PIN_CONFIG_KEY)||'null');
 try{
  if(form.dataset.confirm==='1'){
   const first=form.dataset.firstPin;delete form.dataset.firstPin;delete form.dataset.confirm;
   if(pin!==first){description.textContent='Kies een persoonlijke zescijferige pincode.';submit.textContent='Pincode instellen';input.value='';syncPinDots();error.textContent='De pincodes komen niet overeen. Probeer opnieuw.';return}
   const salt=Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('');
   localStorage.setItem(PIN_CONFIG_KEY,JSON.stringify({salt,hash:await pinDigest(pin,salt),version:1}));
   description.textContent='Voer je pincode in om verder te gaan.';submit.textContent='Ontgrendelen';input.setAttribute('autocomplete','current-password');if(PIN_MANUAL_ONLY)pinLockNow();else pinUnlock();return;
  }
  if(!current){form.dataset.firstPin=pin;form.dataset.confirm='1';description.textContent='Voer dezelfde pincode nogmaals in.';submit.textContent='Pincode bevestigen';input.value='';syncPinDots();input.setAttribute('autocomplete','new-password');error.textContent='';return}
  const actual=await pinDigest(pin,current.salt);
  if(actual===current.hash){pinFailures=0;pinUnlock()}else{pinFailures++;error.textContent='Pincode onjuist. Probeer opnieuw.';input.value='';syncPinDots();input.focus()}
 }catch(err){error.textContent='Beveiligde pincode-opslag is niet beschikbaar in deze browser.'}
});
input.addEventListener('input',()=>{input.value=input.value.replace(/\D/g,'').slice(0,6)});
const dots=document.getElementById('pinDots');
const keypad=document.getElementById('pinKeypad');
function syncPinDots(){const value=input.value;[...dots.children].forEach((dot,i)=>dot.classList.toggle('filled',i<value.length))}
keypad.addEventListener('click',event=>{const key=event.target.closest('button');if(!key)return;if(key.hasAttribute('data-digit')){if(input.value.length<6)input.value+=key.dataset.digit}else if(key.hasAttribute('data-delete')){input.value=input.value.slice(0,-1)}syncPinDots();error.textContent='';});
input.addEventListener('input',syncPinDots);
syncPinDots();
if(!config){description.textContent='Stel een persoonlijke pincode van 6 cijfers in.';submit.textContent='Pincode instellen'}else{description.textContent='Voer je pincode in om verder te gaan.';submit.textContent='Ontgrendelen'}
setupPinSecurityControls();
if(PIN_MANUAL_ONLY){
 if(localStorage.getItem(PIN_MANUAL_KEY)==='1'){pinUnlocked=false;pinLockVisible();}
 else {pinUnlocked=true;if(!document.getElementById('pinLock').classList.contains('memento-welcome-mode'))pinHideLock();}
 updatePinSecurityControls();return;
}
if(!pinRestoreRecentSession(config)){
 pinForgetSession();pinLockVisible();
}
updatePinSecurityControls();
['pointerdown','keydown','touchstart','scroll'].forEach(evt=>document.addEventListener(evt,()=>{
 if(pinUnlocked&&!document.hidden)resetPinIdleTimer(true)
},{passive:true}));
document.addEventListener('visibilitychange',()=>{
 if(!document.hidden){ // A return from Google is not considered a new user action.
  if(pinCheckExpiry())resetPinIdleTimer(false)
 }
});
window.addEventListener('focus',()=>{if(pinCheckExpiry())resetPinIdleTimer(false)});
window.addEventListener('pageshow',()=>{if(pinCheckExpiry())resetPinIdleTimer(false)});
// Deliberately do not lock on pagehide: same-tab OAuth return may restore the page.
}
/* V9 dashboard bridge: reads existing in-memory state without persisting or migrating. */
window.MementoFinanceBridgeV9={
 state:()=>state,scope:()=>dashboardScope,period:()=>dashboardPeriodMode,month:()=>selectedMonth,
 money:v=>money(v),esc:v=>esc(v),balance:id=>accountBalance(id),parts:t=>txParts(t),flow:key=>dashboardAccountFlow(key),
 dateNow:()=>dateNow(),changeView:view=>changeView(view),edit:id=>transactionModal(id),
 renderTransactions:()=>renderTransactions(),render:()=>renderDashboard(),
 drilldown:({from,to,ids,category='',type='all'})=>{changeView('transactions');document.getElementById('txSearch').value='';document.getElementById('txTypeFilter').value=type;document.getElementById('txCategoryFilter').value=category||'all';document.getElementById('txSubcategoryFilter').value='all';document.getElementById('txPersonFilter').value='all';document.getElementById('txAccountFilter').value=ids.includes('joint')?'joint':'personalBundle';document.getElementById('txFrom').value=from;document.getElementById('txTo').value=to;txPage=1;renderTransactions();},
 setScope:scope=>{dashboardScope=scope==='joint'?'joint':'personal';if(dashboardScope==='joint'&&dashboardPeriodMode==='salary')dashboardPeriodMode='month';try{localStorage.setItem('UK_DASHBOARD_SCOPE',dashboardScope)}catch(e){}},
 setPeriod:mode=>setDashboardPeriodMode(mode),
 subscribe:callback=>{const original=renderDashboard;renderDashboard=function(...args){const result=original.apply(this,args);callback();return result;};}
};

